"use strict";
function liveN73Keys(){return authenticKeys().replace('class="real-n73-controls"','class="real-n73-controls device-controls"').replace('class="real-keydeck"','class="real-keydeck live-keydeck"').replace('<div class="real-stick"><i></i></div>','<div class="real-stick live-joystick"><i></i><button data-phone-dir="up" aria-label="手机方向上"></button><button data-phone-dir="left" aria-label="手机方向左"></button><button data-phone-ok aria-label="手机确认"></button><button data-phone-dir="right" aria-label="手机方向右"></button><button data-phone-dir="down" aria-label="手机方向下"></button></div>').replaceAll('（关机）','').replace('aria-label="N73左选择键"','data-phone-soft="left" aria-label="N73左选择键"').replace('aria-label="N73右选择键"','data-phone-soft="right" aria-label="N73右选择键"').replace('aria-label="N73通话键"','data-phone-app="contacts" aria-label="N73通话键"').replace('aria-label="N73结束键"','data-phone-app="home" aria-label="N73结束键"').replace('aria-label="N73菜单键"','data-phone-app="home" aria-label="N73菜单键"').replace('aria-label="N73多媒体键"','data-phone-app="music" aria-label="N73多媒体键"').replace('aria-label="N73编辑键"','data-model-edit aria-label="N73编辑键"').replace('aria-label="N73清除键"','data-model-clear aria-label="N73清除键"').replace(/aria-label="N73数字键([0-9*#])"/g,'data-phone-key="$1" aria-label="手机按键 $1"');}
const liveN73RenderBase=renderPhoneLab;
renderPhoneLab=function(){let h=liveN73RenderBase();if(phoneState.model!=='n73')return h;const device=`<div class="museum-device model-n73 real-n73 live-real-n73" id="museum-device"><button class="real-power" data-phone-app="home" aria-label="N73顶部电源 / 待机">⏻</button><div class="real-earpiece"><i></i><i></i><i></i><i></i><i></i></div><div class="real-camera"></div><div class="real-name">NOKIA <span>Nseries</span></div><div class="real-screen device-screen"><div class="device-status"><span>▂▄▆ 中国移动</span><b>${date.slice(0,4)} ▰</b></div><div class="device-app-title">${escapeHTML(phoneApps.find(x=>x[0]===phoneState.app)?.[1]||'桌面')}<span>时光网络</span></div><div id="device-viewport" class="device-viewport">${phoneScreen()}</div><div class="device-softkeys"><button data-phone-soft="left">选项</button><button data-phone-soft="right">返回</button></div></div><span class="real-side-volume">━<br>━</span>${liveN73Keys()}<span class="real-mic">•</span></div>`;return h.replace(/<div class="museum-device[^>]*id="museum-device">[\s\S]*?<aside class="lab-side-ad">/,device+'</div><aside class="lab-side-ad">');};
document.addEventListener('click',e=>{const b=e.target.closest('[data-phone-key]');if(!b||phoneState.model!=='n73'||['java','snake','games','arcade'].includes(phoneState.app))return;const view=document.querySelector('#device-viewport'),a=document.activeElement;const field=a&&view?.contains(a)&&a.matches('input:not([readonly]),textarea')?a:view?.querySelector('input:not([readonly]):not([type=file]),textarea');if(!field)return;e.preventDefault();e.stopImmediatePropagation();const key=b.dataset.phoneKey;const start=field.selectionStart??field.value.length,end=field.selectionEnd??start;field.setRangeText(key,start,end,'end');field.dispatchEvent(new Event('input',{bubbles:true}));field.focus();},true);
nightShop.positions={};try{const p=JSON.parse(localStorage.getItem(tideStoreKey)||'null')?.expansion?.shop?.positions;for(const id of ['cards','battery','slip'])if(p?.[id]&&Number.isFinite(p[id].x)&&Number.isFinite(p[id].y))nightShop.positions[id]={x:Math.max(0,Math.min(1,p[id].x)),y:Math.max(0,Math.min(1,p[id].y))};}catch{}
function shopPosition(id,x,y){if(!['cards','battery','slip'].includes(id)||!Number.isFinite(x)||!Number.isFinite(y))return false;nightShop.positions[id]={x:Math.max(.04,Math.min(.8,x)),y:Math.max(.04,Math.min(.72,y))};tideSave();return true;}
function shopDragTo(id,dx,dy,el){const parent=el.closest('.closeup-table'),p=parent?.getBoundingClientRect(),r=el.getBoundingClientRect();const moved=shopDragResolve(id,dx,dy);if(moved&&p?.width&&p?.height)shopPosition(id,(r.left+dx-p.left)/p.width,(r.top+dy-p.top)/p.height);return moved;}
const livePutLayerBase=shopPutLayer;
shopPutLayer=function(id){const ok=livePutLayerBase(id);if(ok){delete nightShop.positions[id];if(id==='cards')delete nightShop.positions.battery;tideSave();}return ok;};
const liveObjectBase=shopObjectMarkup;
shopObjectMarkup=function(){let h=liveObjectBase();for(const [id,cls] of [['cards','aside-cards'],['battery','aside-battery'],['slip','prop prop-ledger ledger-aside']]){const p=nightShop.positions[id];if(p)h=h.replace(`class="${cls}"`,`class="${cls}" style="left:${(p.x*100).toFixed(2)}%;top:${(p.y*100).toFixed(2)}%;bottom:auto;transform:rotate(${id==='battery'?12:-9}deg)"`);}return h;};
// A saved physical observation supplies an optional corroborating note, never a destination hint.
const liveChatBase=shopChatChoose;
shopChatChoose=function(id){const ok=liveChatBase(id);if(ok&&id==='receipt'&&!nightShop.evidenceRead.includes('receipt-crosscheck')){nightShop.evidenceRead.push('receipt-crosscheck');tideSave();}return ok;};
const liveSmsBase=tideSms;
tideSms=function(){const b=liveSmsBase();if(tide.device!=='black'||!nightShop.evidenceRead.includes('receipt-crosscheck'))return b;if(tideView==='shop:repair-sms')return tideFrame('店主 / 维修便条',`<div class="deep-chat"><p>那张0731是流水单，不是机身编号。五块钱清的触点，没有换卡。</p><p>他说不用备份。我还是把空卡袋留下来了，怕他回来找。</p><p>22:40是他在纸背上自己写的，我没问是哪班车。</p><p>最后一条没有发出：他交钱的时候，袖口是干的。</p></div>${tideBtn('sms','返回收件箱')}`);return b.replace('<div class="deep-contact-list">','<div class="deep-contact-list"><button data-live-repair>店主 / 0731维修便条</button>');};
try{const p=JSON.parse(localStorage.getItem(tideStoreKey)||'null')?.expansion?.shop?.evidenceRead;if(p?.includes('receipt-crosscheck'))nightShop.evidenceRead.push('receipt-crosscheck');}catch{}
document.addEventListener('click',e=>{if(!e.target.closest('[data-live-repair]'))return;tideView='shop:repair-sms';refreshPhone();});
